import{_ as d,o as n,c as a,a5 as r}from"./chunks/framework.R-FQ1xZ2.js";const c=JSON.parse('{"title":"L0 · 编程与工程基础","description":"","frontmatter":{"title":"L0 · 编程与工程基础","layer":"l0","layerTitle":"L0 · 编程与工程基础","order":0,"points":[],"freq":"高","hours":132,"tags":["foundation","python","engineering"]},"headers":[],"relativePath":"kb/l0-foundation/index.md","filePath":"kb/l0-foundation/index.md","lastUpdated":null}'),o={name:"kb/l0-foundation/index.md"};function e(l,t,i,s,h,f){return n(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="l0-·-编程与工程基础" tabindex="-1">L0 · 编程与工程基础 <a class="header-anchor" href="#l0-·-编程与工程基础" aria-label="Permalink to &quot;L0 · 编程与工程基础&quot;">​</a></h1><blockquote><p>本层知识点导览 ｜ <strong>30 个知识点，13 个页面，约 132 小时</strong></p></blockquote><h2 id="这一层在解决什么问题" tabindex="-1">这一层在解决什么问题 <a class="header-anchor" href="#这一层在解决什么问题" aria-label="Permalink to &quot;这一层在解决什么问题&quot;">​</a></h2><p>L0 是整座知识体系的<strong>底座层</strong>：它不讲模型、不讲微调、不讲 Agent 原理，只解决一件事——<strong>你能不能把想法变成一个别人也能跑起来的东西</strong>。</p><p>这一层的内容全部来自同一个判据：<strong>面试官问「然后呢」的时候，你有没有东西可答。</strong> 你在简历上写了「基于 Milvus 做了混合检索 Agent」，面试官会接着问：服务怎么起的（<code>L0-08</code> <code>L0-07</code>）、接口怎么设计的（<code>L0-09</code> <code>L0-10</code>）、怎么做到逐字输出（<code>L0-11</code>）、数据存哪（<code>L0-12</code> <code>L0-13</code>）、线上答错了怎么查（<code>L0-17</code>）、换一家模型要改多少代码（<code>L0-16</code> <code>L0-23</code>）、模型服务挂了会怎样（<code>L0-24</code>）、这一天要花多少钱（<code>L0-25</code>）。<strong>这些问题不需要你会训模型，但答不上来，前一句话就白说了。</strong></p><p>学这一层的正确姿势不是「看完」，而是<strong>跟着做</strong>：每一页的「和你自己的项目对上号」都把知识点钉在两个真实项目（YYHelp v2 与科研文献 RAG）的具体实现上——那些文件里写着的设计理由，就是这一层最好的教材。<strong>能把这些理由用自己的话讲一遍，这一项就算过了。</strong></p><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><p>按「先能跑 → 再写对 → 再接起来 → 再抗住 → 再讲清」的顺序排；表中的学时是该页各知识点学时之和，与每页 frontmatter 的 <code>hours</code> 一致。</p><table tabindex="0"><thead><tr><th>顺序</th><th>页面</th><th>覆盖知识点</th><th>面试频率</th><th>学时</th></tr></thead><tbody><tr><td>1</td><td><a href="/learn/kb/l0-foundation/01-python-types-and-config.html">Python 类型与数据校验</a></td><td>L0-01 / L0-26</td><td>高</td><td>7</td></tr><tr><td>2</td><td><a href="/learn/kb/l0-foundation/02-async-concurrency.html">asyncio、并发控制与超时重试</a></td><td>L0-02 / L0-11</td><td>高</td><td>9</td></tr><tr><td>3</td><td><a href="/learn/kb/l0-foundation/03-testing-and-di.html">测试、mock 与可测性</a></td><td>L0-04</td><td>中</td><td>5</td></tr><tr><td>4</td><td><a href="/learn/kb/l0-foundation/04-env-and-delivery.html">环境、依赖与交付形态</a></td><td>L0-03 / L0-08 / L0-07</td><td>中</td><td>10</td></tr><tr><td>5</td><td><a href="/learn/kb/l0-foundation/05-git-and-secrets.html">Git 协作、多版本与密钥管理</a></td><td>L0-05 / L0-06</td><td>高</td><td>4</td></tr><tr><td>6</td><td><a href="/learn/kb/l0-foundation/06-http-fastapi-sse.html">HTTP 语义与 FastAPI 服务骨架</a></td><td>L0-09 / L0-10</td><td>高</td><td>9</td></tr><tr><td>7</td><td><a href="/learn/kb/l0-foundation/07-sql-and-cache.html">数据层：SQL、缓存与读写路径</a></td><td>L0-12 / L0-13</td><td>高</td><td>9</td></tr><tr><td>8</td><td><a href="/learn/kb/l0-foundation/08-logging-config-release.html">日志、配置开关与版本发布</a></td><td>L0-17 / L0-18 / L0-19</td><td>中</td><td>6</td></tr><tr><td>9</td><td><a href="/learn/kb/l0-foundation/09-algorithms-and-complexity.html">算法与复杂度</a></td><td>L0-14 / L0-15</td><td>高</td><td>43</td></tr><tr><td>10</td><td><a href="/learn/kb/l0-foundation/10-patterns-and-di.html">设计模式与依赖注入</a></td><td>L0-16 / L0-23</td><td>中</td><td>6</td></tr><tr><td>11</td><td><a href="/learn/kb/l0-foundation/11-robustness-cost-tooling.html">健壮性、成本与工具链</a></td><td>L0-24 / L0-25 / L0-29 / L0-30</td><td>高</td><td>13</td></tr><tr><td>12</td><td><a href="/learn/kb/l0-foundation/12-doc-parsing-and-text.html">文档解析与文本清洗</a></td><td>L0-27 / L0-28</td><td>中</td><td>6</td></tr><tr><td>13</td><td><a href="/learn/kb/l0-foundation/13-demo-frontends.html">演示层：三个前端最小可用</a></td><td>L0-20 / L0-21 / L0-22</td><td>中</td><td>13</td></tr></tbody></table><p><strong>本层合计</strong>：30 个知识点，约 132 小时。</p><p>这个顺序不是唯一解，但有三条判断值得说明：</p><ul><li><strong>序号不等于优先级。</strong> 第 9 页（算法，43h）学时最长，但它是<strong>笔试门槛</strong>——建议从第一天就开始每天分走 45–60 分钟刷题，而不是等前 8 页学完再开始。学时的含义是「累计投入」，不是「排他占用」。</li><li><strong>第 12 页可以提前做。</strong> 它只依赖 Python 本身；如果你手上正好有一份脏 PDF 要处理，先做它比按顺序学更划算。第 13 页（演示层）建议等第 6 页的接口定稿之后再动——<strong>先定契约再写界面</strong>，反过来会返工。</li></ul><h2 id="覆盖自检" tabindex="-1">覆盖自检 <a class="header-anchor" href="#覆盖自检" aria-label="Permalink to &quot;覆盖自检&quot;">​</a></h2><p>大纲 L0 的 30 个编号逐条落到哪一页（本层每个编号<strong>出现且只出现一次</strong>）：</p><table tabindex="0"><thead><tr><th>编号</th><th>知识点</th><th>落在哪一页</th></tr></thead><tbody><tr><td>L0-01</td><td>Python 类型与工程规范</td><td><a href="/learn/kb/l0-foundation/01-python-types-and-config.html">01 Python 类型与数据校验</a></td></tr><tr><td>L0-02</td><td>asyncio 与并发基础</td><td><a href="/learn/kb/l0-foundation/02-async-concurrency.html">02 asyncio、并发控制与超时重试</a></td></tr><tr><td>L0-03</td><td>包管理与虚拟环境</td><td><a href="/learn/kb/l0-foundation/04-env-and-delivery.html">04 环境、依赖与交付形态</a></td></tr><tr><td>L0-04</td><td>测试与 mock</td><td><a href="/learn/kb/l0-foundation/03-testing-and-di.html">03 测试、mock 与可测性</a></td></tr><tr><td>L0-05</td><td>Git 与协作流</td><td><a href="/learn/kb/l0-foundation/05-git-and-secrets.html">05 Git 协作、多版本与密钥管理</a></td></tr><tr><td>L0-06</td><td>环境变量与密钥管理</td><td><a href="/learn/kb/l0-foundation/05-git-and-secrets.html">05 Git 协作、多版本与密钥管理</a></td></tr><tr><td>L0-07</td><td>Linux 命令行与服务器基础</td><td><a href="/learn/kb/l0-foundation/04-env-and-delivery.html">04 环境、依赖与交付形态</a></td></tr><tr><td>L0-08</td><td>Docker 镜像与容器</td><td><a href="/learn/kb/l0-foundation/04-env-and-delivery.html">04 环境、依赖与交付形态</a></td></tr><tr><td>L0-09</td><td>HTTP 与 REST 语义</td><td><a href="/learn/kb/l0-foundation/06-http-fastapi-sse.html">06 HTTP 语义与 FastAPI 服务骨架</a></td></tr><tr><td>L0-10</td><td>FastAPI 服务骨架</td><td><a href="/learn/kb/l0-foundation/06-http-fastapi-sse.html">06 HTTP 语义与 FastAPI 服务骨架</a></td></tr><tr><td>L0-11</td><td>SSE / WebSocket 流式传输</td><td><a href="/learn/kb/l0-foundation/02-async-concurrency.html">02 asyncio、并发控制与超时重试</a></td></tr><tr><td>L0-12</td><td>关系型数据库与 SQL</td><td><a href="/learn/kb/l0-foundation/07-sql-and-cache.html">07 数据层：SQL、缓存与读写路径</a></td></tr><tr><td>L0-13</td><td>Redis 与缓存基础</td><td><a href="/learn/kb/l0-foundation/07-sql-and-cache.html">07 数据层：SQL、缓存与读写路径</a></td></tr><tr><td>L0-14</td><td>数据结构与算法（面试向）</td><td><a href="/learn/kb/l0-foundation/09-algorithms-and-complexity.html">09 算法与复杂度</a></td></tr><tr><td>L0-15</td><td>复杂度分析</td><td><a href="/learn/kb/l0-foundation/09-algorithms-and-complexity.html">09 算法与复杂度</a></td></tr><tr><td>L0-16</td><td>设计模式在 LLM 工程中的应用</td><td><a href="/learn/kb/l0-foundation/10-patterns-and-di.html">10 设计模式与依赖注入</a></td></tr><tr><td>L0-17</td><td>日志与结构化日志</td><td><a href="/learn/kb/l0-foundation/08-logging-config-release.html">08 日志、配置开关与版本发布</a></td></tr><tr><td>L0-18</td><td>配置文件与实验开关</td><td><a href="/learn/kb/l0-foundation/08-logging-config-release.html">08 日志、配置开关与版本发布</a></td></tr><tr><td>L0-19</td><td>版本与发布（语义化版本）</td><td><a href="/learn/kb/l0-foundation/08-logging-config-release.html">08 日志、配置开关与版本发布</a></td></tr><tr><td>L0-20</td><td>前端最小可用：Streamlit</td><td><a href="/learn/kb/l0-foundation/13-demo-frontends.html">13 演示层：三个前端最小可用</a></td></tr><tr><td>L0-21</td><td>前端最小可用：Gradio</td><td><a href="/learn/kb/l0-foundation/13-demo-frontends.html">13 演示层：三个前端最小可用</a></td></tr><tr><td>L0-22</td><td>前端最小可用：React 基础</td><td><a href="/learn/kb/l0-foundation/13-demo-frontends.html">13 演示层：三个前端最小可用</a></td></tr><tr><td>L0-23</td><td>依赖注入与分层架构</td><td><a href="/learn/kb/l0-foundation/10-patterns-and-di.html">10 设计模式与依赖注入</a></td></tr><tr><td>L0-24</td><td>异常处理与降级</td><td><a href="/learn/kb/l0-foundation/11-robustness-cost-tooling.html">11 健壮性、成本与工具链</a></td></tr><tr><td>L0-25</td><td>成本与配额意识</td><td><a href="/learn/kb/l0-foundation/11-robustness-cost-tooling.html">11 健壮性、成本与工具链</a></td></tr><tr><td>L0-26</td><td>数据序列化与校验</td><td><a href="/learn/kb/l0-foundation/01-python-types-and-config.html">01 Python 类型与数据校验</a></td></tr><tr><td>L0-27</td><td>文件与文档解析基础</td><td><a href="/learn/kb/l0-foundation/12-doc-parsing-and-text.html">12 文档解析与文本清洗</a></td></tr><tr><td>L0-28</td><td>正则与文本清洗</td><td><a href="/learn/kb/l0-foundation/12-doc-parsing-and-text.html">12 文档解析与文本清洗</a></td></tr><tr><td>L0-29</td><td>VS Code / Cursor 与调试器</td><td><a href="/learn/kb/l0-foundation/11-robustness-cost-tooling.html">11 健壮性、成本与工具链</a></td></tr><tr><td>L0-30</td><td>代码阅读能力</td><td><a href="/learn/kb/l0-foundation/11-robustness-cost-tooling.html">11 健壮性、成本与工具链</a></td></tr></tbody></table><p><strong>说明</strong>：上表 30 个编号<strong>每个只出现一次</strong>，页面与上表一一对应：13 页 + 本导览。学时按页分配（各页 frontmatter 的 <code>hours</code>），合计等于大纲的 132 小时。</p><h2 id="必须能画出来的图" tabindex="-1">必须能画出来的图 <a class="header-anchor" href="#必须能画出来的图" aria-label="Permalink to &quot;必须能画出来的图&quot;">​</a></h2><p>这些图不是装饰——面试白板题、项目讲解、写文档时都要用。<strong>能当场画出来，说明你真的理解了数据与控制的流动方向。</strong></p><ul><li>[ ] <strong>一次流式问答的时序图</strong>：用户 → 服务 → 检索 → 生成 → SSE 分帧，含首字延迟发生在哪一刻（<a href="/learn/kb/l0-foundation/06-http-fastapi-sse.html">06</a>）</li><li>[ ] <strong>一条链路的降级决策图</strong>：每个依赖失效时走哪条路、用户看到什么、记什么（<a href="/learn/kb/l0-foundation/11-robustness-cost-tooling.html">11</a>）</li><li>[ ] <strong>请求穿越中间件链的时序图</strong>：限流 → 鉴权与 trace_id → 缓存 → 处理器 → 脱敏与日志（<a href="/learn/kb/l0-foundation/10-patterns-and-di.html">10</a>）</li><li>[ ] <strong>缓存读写路径图</strong>：Cache-Aside 的读回填与「更新库 + 删除缓存」的写路径（<a href="/learn/kb/l0-foundation/07-sql-and-cache.html">07</a>）</li><li>[ ] <strong>容器双探针状态机</strong>：为什么「端口开着」不等于「可以接流量」（<a href="/learn/kb/l0-foundation/04-env-and-delivery.html">04</a>）</li><li>[ ] <strong>可追溯链路图</strong>：trace_id 在入口生成 → 日志贯穿 → 响应头回传 → 用户报障可查（<a href="/learn/kb/l0-foundation/08-logging-config-release.html">08</a>）</li><li>[ ] <strong>算法判定路径图</strong>：从题目特征到二分 / 滑窗 / 哈希 / 堆 / 图的选择（<a href="/learn/kb/l0-foundation/09-algorithms-and-complexity.html">09</a>）</li><li>[ ] <strong>文档入库链路图</strong>：解析 → 规范化 → 质量门禁 → 切块 → 入索引，并标出每一环的静默失败点（<a href="/learn/kb/l0-foundation/12-doc-parsing-and-text.html">12</a>）</li><li>[ ] <strong>演示层与服务端的契约图</strong>：哪些职责在前端、哪些必须在服务端（<a href="/learn/kb/l0-foundation/13-demo-frontends.html">13</a>）</li></ul><h2 id="这一层最容易挂在哪" tabindex="-1">这一层最容易挂在哪 <a class="header-anchor" href="#这一层最容易挂在哪" aria-label="Permalink to &quot;这一层最容易挂在哪&quot;">​</a></h2><p>以下是面试反馈里反复出现的失分模式，按出现频率排序：</p><ol><li><strong>「用了 X」但说不出为什么用它。</strong> 简历写 Milvus、LangGraph、SSE，被问「为什么不用别的」就沉默。<strong>修法</strong>：每个技术选择都要能说出一条被排除的替代方案，以及排除它的具体理由（规模、变量可控性、成本、团队熟悉度都算理由）。</li><li><strong>只讲「成功路径」，不讲「失败路径」。</strong> 答不出「模型超时怎么办」「检索返回空怎么办」「用户重复提交怎么办」。<strong>修法</strong>：给每条链路补充一张降级表（<a href="/learn/kb/l0-foundation/11-robustness-cost-tooling.html">11</a>）。</li><li><strong>量化全是形容词。</strong> 「大幅提升了准确性」「响应很快」——面试官无法验证，也无法记住。<strong>修法</strong>：换成可验证的量：<code>recall@5</code>、P95 延迟、token 用量、拒答率；<strong>没有测过就明说没测</strong>，这比编一个数字安全得多。</li><li><strong>工程细节一问就空。</strong> 「别人 clone 下来能跑吗」「一天花多少钱」「线上答错了怎么查」——这三问几乎是固定搭配，考察的是<strong>你有没有把项目当成一个会被别人使用的系统</strong>。<strong>修法</strong>：把 <a href="/learn/kb/l0-foundation/04-env-and-delivery.html">04</a>、<a href="/learn/kb/l0-foundation/07-sql-and-cache.html">07</a>、<a href="/learn/kb/l0-foundation/08-logging-config-release.html">08</a> 三页的自检清单过一遍。</li><li><strong>代码阅读能力被低估。</strong> 面试官问「你读过什么框架源码」时，答「没读过，都是照着教程写」会立刻降低技术可信度；而能说清「我读了状态图那个模块，它把每个字段的 reducer 写成一张表，还用一条『故意配错』的测试证明断言能红」的人，展示的是<strong>可迁移的工程判断力</strong>。<strong>修法</strong>：从自己项目里真正用到的那几个库入手，带着一个具体问题去读（<a href="/learn/kb/l0-foundation/11-robustness-cost-tooling.html">11</a>）。</li></ol>',22)])])}const u=d(o,[["render",e]]);export{c as __pageData,u as default};
